import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';
import Header from '../Components/Header'; // Importing the Header component
import Footer from '../Components/Footer'; // Importing the Footer component
import Modal from 'react-modal';
import '../CSS/moviepage.css'; // Importing the moviepage.css file

// Defining constants for the API key and base URL
const apiKey = '499d99db6ce23991d21afde0deede0f1';
const baseUrl = 'https://api.themoviedb.org/3';
const closeTrailer = () => {
  setTrailerVideoKey(null);
};


function MoviePage() {
  // Using the useParams hook to get the ID of the selected movie from the URL parameter
  const { id } = useParams();

  // Setting up state for the movie details, cast, reviews, and trailer video
  const [movieDetails, setMovieDetails] = useState(null);
  const [cast, setCast] = useState([]);
  const [showAllCast, setShowAllCast] = useState(false);
  const [reviews, setReviews] = useState([]);
  const [trailerVideoKey, setTrailerVideoKey] = useState(null);

  // Using an effect hook to fetch data from the API when the component mounts
  useEffect(() => {
    const fetchData = async () => {
      // Fetching the details for the selected movie from the TMDb API
      const detailsResponse = await axios.get(
        `${baseUrl}/movie/${id}`,
        {
          params: {
            api_key: apiKey,
          },
        }
      );
      setMovieDetails(detailsResponse.data);
      // Fetching the credits for the selected movie from the TMDb API
      const creditsResponse = await axios.get(
        `${baseUrl}/movie/${id}/credits`,
        {
          params: {
            api_key: apiKey,
          },
        }
        );
        setCast(creditsResponse.data.cast.slice(0, 5));
      // Fetching the reviews for the selected movie from the TMDb API
      const reviewsResponse = await axios.get(
        `${baseUrl}/movie/${id}/reviews`,
        {
          params: {
            api_key: apiKey,
          },
        }
      );
      setReviews(reviewsResponse.data.results);

      // Fetching videos for the selected movie from the TMDb API
      const videosResponse = await axios.get(
        `${baseUrl}/movie/${id}/videos`,
        {
          params: {
            api_key: apiKey,
          },
        }
      );
      // Finding a trailer video and setting its key in state
      const trailerVideo = videosResponse.data.results.find(
        (video) => video.type === 'Trailer'
      );
      if (trailerVideo) {
        setTrailerVideoKey(trailerVideo.key);
      }
    };
    fetchData();
  }, [id]);

  // Rendering the Header, movie details, cast, reviews, and Footer
  return (
    <>
      <Header />
      <div className="movie-page">
      {trailerVideoKey && (
  <Modal
    isOpen={true}
    onRequestClose={closeTrailer}
    style={{
      overlay: {
        backgroundColor: 'rgba(0, 0, 0, 0.75)',
      },
      content: {
        top: '50%',
        left: '50%',
        right: 'auto',
        bottom: 'auto',
        marginRight: '-50%',
        transform: 'translate(-50%, -50%)',
        width: '80%',
        height: '80%',
        padding: 0,
        overflow : 'hidden',
      },
    }}
  >
    <div
      className={`modal-content ${trailerVideoKey ? 'open' : ''}`}
      style={{ position: 'relative', width: '100%', height: '100%' }} // Add styles to make the div fill its parent container
    >
      
      <iframe
        src={`https://www.youtube.com/embed/${trailerVideo.key}`}
        title={trailerVideo.name}
        allowFullScreen
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
        }}
      />
    </div>
  </Modal>
)}

        <div className="movie-details">
          {movieDetails && (
            <>
              <h1>{movieDetails.title}</h1>
              <p>{movieDetails.overview}</p>
            </>
          )}
        </div>
        <h2>Cast</h2>
        <ul className="cast-list">
          {(showAllCast ? cast : cast.slice(0, 5)).map((actor) => (
          <li key={actor.id}>
            <img
            src={`https://image.tmdb.org/t/p/w500${actor.profile_path}`}
            alt={actor.name}
            style={{ height: '100px' }}
            />
            <p>{actor.name}</p>
            </li>
             ))}
             </ul>
             <button onClick={() => setShowAllCast(!showAllCast)}>{showAllCast ? 'Less' : 'More'}</button>
        <h2>Reviews</h2>
        <ul className="reviews-list">
          {reviews.map((review) => (
            <li key={review.id}>{review.content}</li>
          ))}
        </ul>
      </div>
      <Footer />
    </>
  );
}

export default MoviePage;
